document.addEventListener('DOMContentLoaded',function(){var rolesNode=document.getElementById('access-users-assignment-roles-json');var assignmentRoles=[];try{assignmentRoles=JSON.parse(rolesNode?rolesNode.textContent:'[]')||[];}catch(error){assignmentRoles=[];}document.querySelectorAll('[data-user-role-select]').forEach(function(select){var form=select.closest('form');var wrapper=form?.querySelector('[data-branch-assignment-wrapper]');var toggle=function(){if(!wrapper){return;}var show=assignmentRoles.includes(select.value);wrapper.hidden=!show;wrapper.querySelectorAll('input').forEach(function(input){input.disabled=!show;});};select.addEventListener('change',toggle);toggle();});var randomPassword=function(){var chars='ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789!@#$%';return Array.from({length:14},function(){return chars[Math.floor(Math.random()*chars.length)];}).join('');};document.querySelectorAll('[data-password-tools]').forEach(function(group){var input=group.querySelector('input');group.querySelector('[data-password-toggle]')?.addEventListener('click',function(){input.type=input.type==='password'?'text':'password';group.querySelector('[data-password-toggle] i')?.classList.toggle('fa-eye-slash',input.type==='text');});group.querySelector('[data-password-generate]')?.addEventListener('click',function(){input.value=randomPassword();input.type='text';input.dispatchEvent(new Event('input',{bubbles:true}));});});var currentScript=document.currentScript||document.querySelector('script[data-show-create-modal]');if(currentScript?.dataset.showCreateModal==='1'){bootstrap.Modal.getOrCreateInstance(document.getElementById('createUserModal'))?.show();}});